<?php
namespace App\Http\Controllers; use App\Models\ProjectDocument; use Illuminate\Support\Facades\Gate; use Illuminate\Support\Facades\Storage; use Symfony\Component\HttpFoundation\StreamedResponse;
class ProjectDocumentController extends Controller { public function download(ProjectDocument $document):StreamedResponse{Gate::authorize('view',$document->project);abort_unless(Storage::disk($document->disk)->exists($document->path),404);return Storage::disk($document->disk)->download($document->path,basename($document->original_name),['X-Content-Type-Options'=>'nosniff']);} }